customCSS:
.t, .history { color: #555555; }
.join { color: #aac441; }
.part, .quit { color: #555555; }
.kick, .error { color: #fc6028; }
.notice { color: #fda543; }
.action { color: #bb00bb; }
.mode, .nick, .topic, .server { color: #86e2bf; }
.highlight { color: #e0dac4; background-color: #1c2631; border-left: 3px solid #bb00bb; padding-left: 8px; }
.reply { color: #555555; border-left: 2px solid #2d91d0; padding-left: 6px; }
.oper { color: #0d1013; background-color: #fda543; }
.reactions { color: #2d91d0; background-color: #1c2631; }
.card { background-color: #1c2631; border-color: #555555; }
.card-title { color: #2d91d0; }
.card-desc { color: #555555; }
.daychange { color: #555555; border-color: #1c2631; }
